{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Drop and the Debt",
          "intent": "Establish Rhea's death, her transfer into the Ledger's frontier tutorial, and her immediate realization that the 'Mercy Cache' onboarding process is a rigged debt trap.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea identifies the specific wording flaw in the initial survival contract that allows her to reject the predatory starter debt."
        },
        {
          "section_id": 2,
          "title": "The First Exploit",
          "intent": "Rhea executes her first loophole to survive the physical dangers of the drop without accepting the system's poisoned help.",
          "section_role": "escalation",
          "target_scene_count": 2,
          "end_condition": "Rhea successfully bypasses the tutorial debt trigger and secures her first un-skimmed system resource to survive the night."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "The Starter Town Economy",
          "intent": "Rhea navigates the settlement, analyzing the rigged economy, tariffs, and cooldowns to find a safe baseline without falling into the intended debt traps.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea secures basic shelter and sustenance without triggering a systemic debt flag or accepting a predatory loan."
        },
        {
          "section_id": 2,
          "title": "Quest Board Forensics",
          "intent": "Rhea analyzes the local quest board, identifying mathematical discrepancies in risk versus reward to find an exploitable margin.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Rhea completes a low-tier quest using an unintended mechanical interaction, yielding a disproportionate, un-taxed payout."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Reluctant Clerk",
          "intent": "Rhea's unusual success attracts a cynical local clerk who recognizes her anomaly, leading to a tense negotiation of mutual benefit.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea and the clerk form a binding, mutually beneficial, and highly suspicious party contract."
        },
        {
          "section_id": 2,
          "title": "Pooling Data",
          "intent": "Using the clerk's access, Rhea digs into the backend of the local quest payouts, finding hidden administrative residue that shouldn't exist.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Rhea isolates the exact percentage and destination of the systemic skim on local experience gains."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The Field Test",
          "intent": "Rhea and her ally undertake a standard progression quest specifically to monitor the backend math in real-time and force an error.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea triggers a specific combat milestone that forces the system to visibly log the skimmed value in her combat telemetry."
        },
        {
          "section_id": 2,
          "title": "Concrete Proof",
          "intent": "Rhea survives the quest's physical dangers while capturing the administrative data proving institutional theft by the local overseers.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Rhea extracts a physical or digital ledger fragment proving the local overseers are stealing from the System itself."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "Pushing the Exploit",
          "intent": "Rhea uses the ledger fragment to aggressively siphon stolen experience and loot back to herself, leveling rapidly but drawing attention.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Rhea hits a progression threshold that triggers an automated, high-priority system audit on her character."
        },
        {
          "section_id": 2,
          "title": "Overseer Retaliation",
          "intent": "The local authorities realize they are being robbed and send enforcers to collect Rhea's 'debt' by force.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Rhea survives the initial enforcer ambush but is marked with a systemic bounty and severe administrative penalty."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "The Administrative Snare",
          "intent": "The overseers trap Rhea using weaponized debt logic, freezing her assets and restricting her system access to force a surrender.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea is cornered in a restricted zone with her standard system privileges revoked and her health/stamina draining."
        },
        {
          "section_id": 2,
          "title": "The Counter-Loophole",
          "intent": "Rhea must survive physical threats while finding a legal and mechanical counter-loophole to unfreeze her status and turn the trap around.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Rhea successfully files a 'grievance of systemic corruption' that temporarily overrides the overseers' authority and restores her access."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The Counter-Audit",
          "intent": "Rhea assaults the frontier's core Ledger node, using her evidence to trigger a catastrophic feedback loop in the skimming operation.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Rhea breaches the core node's physical defenses and initiates the counter-audit protocol directly into the terminal."
        },
        {
          "section_id": 2,
          "title": "Crashing the Node",
          "intent": "The local system collapses under the weight of its own contradictory rules, granting Rhea massive, un-skimmed progression as the overseers fall.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "The frontier node shatters, transferring the hoarded administrative value directly into Rhea's inventory and stats."
        }
      ]
    },
    {
      "chapter_id": 8,
      "sections": [
        {
          "section_id": 1,
          "title": "Processing the Gains",
          "intent": "Rhea solidifies her build, allocates her massive stat and skill gains, and prepares to flee the collapsing zone before higher authorities arrive.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Rhea finalizes her tier-up class advancement and equips the stolen administrative keys."
        },
        {
          "section_id": 2,
          "title": "Exiting the Frontier",
          "intent": "Rhea and her ally escape the tutorial zone just as higher-tier Ledger authorities arrive to investigate the crash, setting up the next book.",
          "section_role": "resolution",
          "target_scene_count": 2,
          "end_condition": "Rhea crosses the threshold into the wider civic world, leaving the ruined frontier behind."
        }
      ]
    }
  ]
}

